 let publicKey=key.startsWith('sb_publishable_');
 if(!publicKey&&key.startsWith('eyJ'))try{publicKey=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role==='anon';}catch{}
